51.source:
mod params;
use params::{K, KEY_HASH};
use commitment_lib::{commit, commit_totals, fold_batch_acc};

// Corte de rendimiento (yield): la declaracion probada del plan aprobado es
// "los rewards que la app acredita son exactamente el rendimiento que Morpho
// generó sobre los fondos, repartido pro rata", sin revelar balances individuales.
// Delta (yield del vault en el periodo) es publico on-chain sin ZK (recomputable
// con dos eth_call historicos); lo que prueba este circuito es que Sum(reward_i)
// nunca excede Delta (mas alla de polvo de redondeo acotado) y que cada reward_i
// es el floor pro rata honesto de balance_i sobre Delta, sin filtrar balance_i.
struct UserInput {
    balance: Field,
    reward: Field,
    salt: Field,
}

// BAL_BITS=48 fijo (mismo contrato de unidad que circuits-mini/liabilities_batch_mini:
// BAL_SCALE 1e10, unidades de 8 decimales). Literal en vez de params::BAL_BITS: el generic
// de assert_max_bit_size necesita una constante en tiempo de compilacion (Pitfall heredado
// de circuits-mini/liabilities_batch_mini/src/main.nr).
fn assert_bal_bits(v: Field) {
    v.assert_max_bit_size::<48>();
}

// public inputs resultantes, layout [key_hash, C_L, delta] (D-diseño del plan de yield):
// key_hash es un pub PARAM (constrainido contra el ancla KEY_HASH de params.nr, mismo
// rol que en el mini), C_L y delta son el pub RETURN en ese orden (el orden de un tuple
// pub return es el orden de declaracion). delta llega como witness PRIVADO (no pub param)
// y se expone via el return: asi el layout final coincide con [key_hash, cL, delta] que
// FaroYieldRegistry.sol espera (cL en publicInputs[1] igual que SobrecitoRegistry, delta
// nuevo en publicInputs[2]).
fn main(users: [UserInput; K], r: Field, key_hash: pub Field, delta: Field) -> pub (Field, Field) {
    assert(key_hash == KEY_HASH);

    let mut total_balance: Field = 0;
    let mut total_reward: Field = 0;
    let mut commitments: [Field; K] = [0; K];
    for i in 0..K {
        assert_bal_bits(users[i].balance); // rango 48 bits, RF-P1
        assert_bal_bits(users[i].reward); // rango 48 bits, RF-P1
        total_balance = total_balance + users[i].balance;
        total_reward = total_reward + users[i].reward;
        commitments[i] = commit([users[i].balance, users[i].reward], users[i].salt);
    }

    // RF-P2: Sum(reward_i) <= delta, con polvo acotado a < K unidades minimas (el floor
    // pro rata por usuario deja como maximo casi 1 unidad de resto cada uno, K usuarios
    // acotan el polvo total a < K; jamas puede haber inyeccion, sum > delta rechaza).
    // assert_max_bit_size prueba la no negatividad de `dust` sin wraparound de field: si
    // total_reward > delta, `dust` (mod p) queda cerca del modulo (~254 bits), muy por
    // encima de 64 bits, y la prueba se cae aca.
    let dust = delta - total_reward;
    dust.assert_max_bit_size::<64>();
    assert((dust as u64) < (K as u64));

    // RF-P3: pro rata honesto por usuario, floor exacto de la division real
    // (reward_i = floor(delta * balance_i / total_balance)): balance_i*delta -
    // reward_i*total_balance es el resto de esa division, siempre < total_balance
    // cuando el prover uso el floor real; cualquier reward_i inflado o desviado hace
    // que ese resto sea negativo (falla la no negatividad) o exceda total_balance
    // (falla la cota de resto). Los productos (balance_i, reward_i <=48 bits, delta
    // implicitamente acotado por el chequeo de dust arriba) entran holgados en el field.
    for i in 0..K {
        let rhs = users[i].balance * delta;
        let lhs = users[i].reward * total_balance;
        let diff = rhs - lhs;
        diff.assert_max_bit_size::<64>();
        assert((diff as u64) < (total_balance as u64));
    }

    let acc_root = fold_batch_acc(commitments);
    let c_l = commit_totals([total_balance, total_reward], acc_root, r);
    (c_l, delta)
}

// ---------------------------------------------------------------------------
// Tests (D-05 del plan de yield: caso feliz, rechazo de Sum>Delta, rechazo de
// pro rata torcido, rechazo de key_hash ajeno).
// ---------------------------------------------------------------------------

fn empty_users() -> [UserInput; K] {
    [UserInput { balance: 0, reward: 0, salt: 0 }; K]
}

#[test]
fn yield_cut_happy_path() {
    let mut users = empty_users();
    // Un usuario real: balance=1000, reward=100 (floor pro rata exacto de delta=100
    // sobre un total_balance de 1000, unico usuario => reward = delta entero).
    users[0] = UserInput { balance: 1000, reward: 100, salt: 42 };
    let (c_l, delta_out) = main(users, 7, KEY_HASH, 100);
    assert(c_l != 0);
    assert(delta_out == 100);
}

#[test(should_fail)]
fn yield_cut_rejects_sum_reward_over_delta() {
    let mut users = empty_users();
    // reward=100 > delta=50: dust = delta - total_reward queda negativo (mod p, ~254 bits).
    users[0] = UserInput { balance: 1000, reward: 100, salt: 42 };
    let _ = main(users, 7, KEY_HASH, 50);
}

#[test(should_fail)]
fn yield_cut_rejects_skewed_pro_rata() {
    let mut users = empty_users();
    // Dos usuarios con el MISMO balance (1000 cada uno, total_balance=2000) deberian
    // repartirse el delta=100 en partes iguales (50/50). Este caso le da TODO el reward
    // a users[0] y NADA a users[1]: viola el floor pro rata honesto por usuario.
    users[0] = UserInput { balance: 1000, reward: 100, salt: 1 };
    users[1] = UserInput { balance: 1000, reward: 0, salt: 2 };
    let _ = main(users, 7, KEY_HASH, 100);
}

#[test(should_fail)]
fn yield_cut_rejects_wrong_key_hash() {
    let mut users = empty_users();
    users[0] = UserInput { balance: 1000, reward: 100, salt: 42 };
    let _ = main(users, 7, KEY_HASH + 1, 100);
}

54.source:
mod domains;
pub use domains::{DOMAIN_USER_COMMITMENT, DOMAIN_BATCH_ACC, DOMAIN_NODE, DOMAIN_CL};

// El struct `Poseidon2` de la stdlib de Noir (`std::hash::poseidon2::Poseidon2`) es
// `pub(crate)`: no se puede instanciar ni importar desde fuera de la stdlib (verificado
// contra nargo 1.0.0-beta.22 real, no contra un checkout de research). Este struct
// reimplementa el MISMO sponge duplex (rate=3, capacidad=1, `state[RATE]` = IV) sobre la
// primitiva pública `std::hash::poseidon2_permutation`, algoritmo idéntico al de la stdlib
// (mismo perform_duplex/absorb/squeeze), con el nombre `Poseidon2` para que el sitio de
// llamada (`Poseidon2::new(DOMAIN_...)`) lea igual que si fuera la stdlib.
struct Poseidon2 {
    state: [Field; 4],
    cache: [Field; 3],
    cache_size: u32,
}

impl Poseidon2 {
    fn new(iv: Field) -> Self {
        Poseidon2 { state: [0, 0, 0, iv], cache: [0, 0, 0], cache_size: 0 }
    }

    fn absorb(&mut self, input: Field) {
        if self.cache_size == 3 {
            for j in 0..3 {
                self.state[j] += self.cache[j];
            }
            self.state = std::hash::poseidon2_permutation(self.state);
            self.cache[0] = input;
            self.cache_size = 1;
        } else {
            self.cache[self.cache_size] = input;
            self.cache_size += 1;
        }
    }

    fn squeeze(&mut self) -> Field {
        for j in 0..3 {
            if j < self.cache_size {
                self.state[j] += self.cache[j];
            }
        }
        self.state = std::hash::poseidon2_permutation(self.state);
        self.state[0]
    }
}

// WR-02 (09-REVIEW.md): el IV codifica la LONGITUD ademas del dominio, espejo de la
// convencion de la stdlib (que usa iv = len * 2^64 exactamente por esto):
// iv = domain * 2^64 + n_absorbidos. Sin la longitud, el padding con ceros del
// ultimo bloque colisiona entre longitudes: commit([a], b) y commit([a, b], 0)
// producian el mismo estado pre-permutacion [a, b, 0, IV]. El dominio ocupa 136
// bits; corrido 64 bits queda en 200 < 254, sin overlap con el contador.
pub global IV_LEN_SHIFT: Field = 18446744073709551616; // 2^64

fn iv_for(domain: Field, n_absorbed: u32) -> Field {
    domain * IV_LEN_SHIFT + (n_absorbed as Field)
}

// Commitment por usuario: sponge sobre los T balances en orden + el salt, con IV de
// dominio propio. Cierra WR-03 (el spike encadenaba state[0] de una permutación cruda,
// sin capacidad separada del rate).
pub fn commit<let T: u32>(balances: [Field; T], salt: Field) -> Field {
    let mut sponge = Poseidon2::new(iv_for(DOMAIN_USER_COMMITMENT, T + 1));
    for t in 0..T {
        sponge.absorb(balances[t]);
    }
    sponge.absorb(salt);
    sponge.squeeze()
}

// Acumulador de un lote: sponge sobre los K commitments del lote, en orden.
// ponytail: acumulador lineal por lote, no árbol Merkle. Una prueba de inclusión
// de un usuario requiere el lote entero. Si la fase de claim del cliente pide
// inclusión sucinta, esto sube a Merkle sin cambiar la firma pública.
pub fn fold_batch_acc<let K: u32>(commitments: [Field; K]) -> Field {
    let mut sponge = Poseidon2::new(iv_for(DOMAIN_BATCH_ACC, K));
    for i in 0..K {
        sponge.absorb(commitments[i]);
    }
    sponge.squeeze()
}

// Nodo del árbol de agregadores: combina el acumulador de dos hijos.
pub fn fold_node(left_acc: Field, right_acc: Field) -> Field {
    let mut sponge = Poseidon2::new(iv_for(DOMAIN_NODE, 2));
    sponge.absorb(left_acc);
    sponge.absorb(right_acc);
    sponge.squeeze()
}

// C_L (D-06): único output público de la raíz del árbol. Bindea los totales por token,
// el acc_root del árbol de commitments y el blinding r en un solo Field.
pub fn commit_totals<let T: u32>(totals: [Field; T], acc_root: Field, r: Field) -> Field {
    let mut sponge = Poseidon2::new(iv_for(DOMAIN_CL, T + 2));
    for t in 0..T {
        sponge.absorb(totals[t]);
    }
    sponge.absorb(acc_root);
    sponge.absorb(r);
    sponge.squeeze()
}

// Las anclas de VK (EXPECTED_CHILD_KEY_HASH) viven en el params.nr generado de cada
// crate agregador, una por nivel del árbol. Ver circuits/scripts/gen_anchors.py.

#[test]
fn commit_is_deterministic() {
    assert(commit([1, 2], 7) == commit([1, 2], 7));
}

#[test]
fn commit_changes_with_salt() {
    assert(commit([1, 2], 7) != commit([1, 2], 8));
}

#[test]
fn commit_changes_with_balance() {
    assert(commit([1, 2], 7) != commit([2, 1], 7));
}

#[test]
fn domains_are_separated() {
    assert(commit([1], 2) != fold_node(1, 2));
}

// WR-02: antes del encoding de longitud en el IV, estos dos colisionaban
// (mismo estado pre-permutacion [1, 2, 0, IV] con cola de ceros).
#[test]
fn iv_encodes_length() {
    assert(commit([1], 2) != commit([1, 2], 0));
}

#[test]
fn commit_totals_changes_with_blinding() {
    assert(commit_totals([10], 5, 1) != commit_totals([10], 5, 2));
}

// Propiedad de apertura de C_L que el auditor ejerce fuera del circuito con
// (L, acc_root, r) recibidos por view-key (D-06): recomputar commit_totals
// con los mismos tres argumentos da el mismo Field, y cambiar CUALQUIERA de
// los tres (totales, acc_root o blinding) lo cambia.
#[test]
fn commit_totals_opens_deterministically() {
    let totals: [Field; 2] = [100, 200];
    let acc_root = 42;
    let r = 7;
    assert(commit_totals(totals, acc_root, r) == commit_totals(totals, acc_root, r));
}

#[test]
fn commit_totals_changes_with_totals() {
    let acc_root = 42;
    let r = 7;
    assert(commit_totals([100, 200], acc_root, r) != commit_totals([100, 201], acc_root, r));
}

#[test]
fn commit_totals_changes_with_acc_root() {
    let totals: [Field; 2] = [100, 200];
    let r = 7;
    assert(commit_totals(totals, 42, r) != commit_totals(totals, 43, r));
}
